        function timePeriodEventBinder() {
            $('#timePeriod').on('click keydown', function (e) {
                // Handle Enter, Space, or click - open/close
                if (e.type === 'click' || e.keyCode === 13 || e.keyCode === 32) {
                    e.preventDefault();
                    e.stopPropagation();
                    var isOpen = $('#dateRangePopup').is(':visible');
                    if (!isOpen) {
                        $('#dateRangePopup').show();
                        $('#timePeriod').addClass('open').attr('aria-expanded', 'true');
                        // Focus the container to enter focus mode
                        $('#dateRangePopup')[0].focus();
                    } else {
                        $('#dateRangePopup').hide();
                        $('#timePeriod').removeClass('open').attr('aria-expanded', 'false');
                    }
                    return false;
                }
                // Arrow Down - focus first option (excluding Time Period option)
                if (e.keyCode === 40) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (!$('#dateRangePopup').is(':visible')) {
                        $('#dateRangePopup').show();
                        $('#timePeriod').addClass('open').attr('aria-expanded', 'true');
                    }
                    var $firstOption = $('#submittedIn li:visible:not(#liTimePeriod) button').first();
                    if ($firstOption.length) {
                        $firstOption[0].focus();
                    }
                    return false;
                }
                // Arrow Up - focus last option (excluding Time Period option)
                if (e.keyCode === 38) {
                    e.preventDefault();
                    e.stopPropagation();
                    if (!$('#dateRangePopup').is(':visible')) {
                        $('#dateRangePopup').show();
                        $('#timePeriod').addClass('open').attr('aria-expanded', 'true');
                    }
                    var $lastOption = $('#submittedIn li:visible:not(#liTimePeriod) button').last();
                    if ($lastOption.length) {
                        $lastOption[0].focus();
                    }
                    return false;
                }
                // Escape - close if open
                if (e.keyCode === 27) {
                    if ($('#dateRangePopup').is(':visible')) {
                        e.preventDefault();
                        $('#dateRangePopup').hide();
                        $('#timePeriod').removeClass('open').attr('aria-expanded', 'false');
                    }
                }
            });

            // Handle arrow keys on the popup container itself
            $('#dateRangePopup').on('keydown', function (e) {
                if (e.target.id === 'dateRangePopup') {
                    if (e.keyCode === 40) { // Arrow Down - focus first option
                        e.preventDefault();
                        e.stopPropagation();
                        var $firstOption = $('#submittedIn li:visible:not(#liTimePeriod) button').first();
                        if ($firstOption.length) {
                            $firstOption[0].focus();
                        }
                    }
                    if (e.keyCode === 38) { // Arrow Up - focus last option
                        e.preventDefault();
                        e.stopPropagation();
                        var $lastOption = $('#submittedIn li:visible:not(#liTimePeriod) button').last();
                        if ($lastOption.length) {
                            $lastOption[0].focus();
                        }
                    }
                    if (e.keyCode === 27) { // Escape
                        e.preventDefault();
                        $('#dateRangePopup').hide();
                        $('#timePeriod').removeClass('open').attr('aria-expanded', 'false');
                        $('#timePeriod')[0].focus();
                    }
                    if (e.keyCode === 9) { // Tab - close popup
                        $('#dateRangePopup').hide();
                        $('#timePeriod').removeClass('open').attr('aria-expanded', 'false');
                    }
                }
            });

            // Arrow key navigation within dropdown options
            $('#submittedIn').on('keydown', 'button[role="option"]', function (e) {
                var $options = $('#submittedIn li:visible:not(#liTimePeriod) button');
                var currentIndex = $options.index(this);
                var $target = null;

                switch (e.keyCode) {
                    case 40: // Arrow Down
                        e.preventDefault();
                        e.stopPropagation();
                        if (currentIndex < $options.length - 1) {
                            $target = $options.eq(currentIndex + 1);
                        } else {
                            $target = $options.first();
                        }
                        break;
                    case 38: // Arrow Up
                        e.preventDefault();
                        e.stopPropagation();
                        if (currentIndex > 0) {
                            $target = $options.eq(currentIndex - 1);
                        } else {
                            $target = $options.last();
                        }
                        break;
                    case 27: // Escape
                        e.preventDefault();
                        e.stopPropagation();
                        $('#dateRangePopup').hide();
                        $('#timePeriod').removeClass('open').attr('aria-expanded', 'false');
                        $('#timePeriod')[0].focus();
                        break;
                    case 9: // Tab
                        var isLastOption = (currentIndex === $options.length - 1);
                        var isFirstOption = (currentIndex === 0);

                        // Close popup when tabbing forward from last option or backward from first
                        if ((isLastOption && !e.shiftKey) || (isFirstOption && e.shiftKey)) {
                            $('#dateRangePopup').hide();
                            $('#timePeriod').removeClass('open').attr('aria-expanded', 'false');
                        }
                        break;
                }

                if ($target && $target.length) {
                    $target[0].focus();
                }
            });

            $(document).on('click', function (e) {
                if (!$(e.target).closest('.popoutContainer.timePeriod').length) {
                    if ($('#dateRangePopup').is(':visible')) {
                        $('#dateRangePopup').hide();
                        $('#timePeriod').removeClass('open').attr('aria-expanded', 'false');
                    }
                }
            });
        }

